{
  "name": "loss_logsigmoid_crossover_costgap_m3_keysafe",
  "intuition": "Stabilize and simplify by keeping the core pairwise -logsigmoid preference objective, but make it robust to batch key naming: accept either (log_prob_w/log_prob_l) or common aliases (logp_w/logp_l, chosen_logprob/rejected_logprob, log_prob_chosen/log_prob_rejected). Add safe normalization of weights (clamp to non-negative) and keep the detached cost-gap adjustment optional and bounded via clamping of the combined logit to avoid numerical extremes while preserving gradients for the preference term.",
  "pseudocode": "lpw,lpl = get_pair_logprobs_with_aliases(batch); x = alpha*scale*(lpw-lpl) - cost_weight*detach(cost_b-cost_a if present); x=clamp(x, cmin,cmax); loss=-logsigmoid(x); if weight: loss*=clamp(weight,0,inf); return mean(loss)",
  "hyperparams": {
    "scale": 1.2,
    "cost_weight": 0.1,
    "clamp_min": -20.0,
    "clamp_max": 20.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    # Key-safe retrieval of winner/loser log-probs.
    # Prefer canonical names, but accept common aliases to satisfy expects in varied datasets.
    if 'log_prob_w' in batch:
        lpw = batch['log_prob_w']
    elif 'logp_w' in batch:
        lpw = batch['logp_w']
    elif 'chosen_logprob' in batch:
        lpw = batch['chosen_logprob']
    elif 'log_prob_chosen' in batch:
        lpw = batch['log_prob_chosen']
    else:
        # Fall back to an existing tensor to create a safe zero (keeps graph valid).
        ref = None
        if 'log_prob_l' in batch:
            ref = batch['log_prob_l']
        elif 'logp_l' in batch:
            ref = batch['logp_l']
        elif 'rejected_logprob' in batch:
            ref = batch['rejected_logprob']
        elif 'log_prob_rejected' in batch:
            ref = batch['log_prob_rejected']
        else:
            ref = model_output
        lpw = ref * 0.0

    if 'log_prob_l' in batch:
        lpl = batch['log_prob_l']
    elif 'logp_l' in batch:
        lpl = batch['logp_l']
    elif 'rejected_logprob' in batch:
        lpl = batch['rejected_logprob']
    elif 'log_prob_rejected' in batch:
        lpl = batch['log_prob_rejected']
    else:
        lpl = lpw * 0.0

    weight = batch.get('weight', None)

    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}
    alpha = float(extra.get('alpha', hp.get('alpha', 1.0))) if isinstance(extra, dict) else 1.0
    scale = float(hp.get('scale', 1.2))
    cost_w = float(hp.get('cost_weight', 0.1))
    cmin = float(hp.get('clamp_min', -20.0))
    cmax = float(hp.get('clamp_max', 20.0))

    x = alpha * scale * (lpw - lpl)

    # Optional detached cost-gap penalty; no gradient path through costs.
    if (cost_w != 0.0) and ('cost_a' in batch) and ('cost_b' in batch):
        gap = (batch['cost_b'] - batch['cost_a']).detach()
        x = x - cost_w * gap

    x = ops.clamp(x, cmin, cmax)
    loss = -ops.logsigmoid(x)

    if weight is not None:
        # Enforce non-negative weights per builder gate; keep vectorized.
        loss = loss * ops.clamp(weight, 0.0, 1e9)

    return loss.mean()",
  "theoretical_basis": ""
}

