{
  "name": "consensus_logsigmoid_clamped_scale_v2_expects_safe",
  "intuition": "The failure is from missing required input keys (`log_prob_w`, `log_prob_l`) in the builder's expects schema. Stabilize and simplify by (1) declaring these keys explicitly in `expects`, (2) keeping a numerically stable pairwise logistic loss using `-logsigmoid` on the log-prob gap, (3) clamping logits to avoid extreme values and gradient spikes, and (4) making optional weighting safe by normalizing with the (clamped) sum of weights so the loss scale stays consistent across batches.",
  "expects": {
    "log_prob_w": {
      "type": "tensor",
      "desc": "Log-probability (or logit score) for the preferred/winner response.",
      "shape": [
        "batch"
      ]
    },
    "log_prob_l": {
      "type": "tensor",
      "desc": "Log-probability (or logit score) for the dispreferred/loser response.",
      "shape": [
        "batch"
      ]
    },
    "weight": {
      "type": "tensor",
      "desc": "Optional non-negative per-example weight.",
      "shape": [
        "batch"
      ],
      "optional": true
    }
  },
  "pseudocode": "d = log_prob_w - log_prob_l; x = clamp(alpha*scale*d, clamp_min, clamp_max); per = -logsigmoid(x); if weight: return sum(per*weight)/max(sum(weight), eps); else: return mean(per)",
  "hyperparams": {
    "scale": 1.2,
    "clamp_min": -20.0,
    "clamp_max": 20.0,
    "eps": 1e-08
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) ranking loss on the score gap, with logit clamping for numerical stability and optional normalized non-negative weighting.",
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}\n    alpha = float(extra.get('alpha', 1.0)) if isinstance(extra, dict) else 1.0\n\n    scale = float(hp.get('scale', 1.2))\n    cmin = float(hp.get('clamp_min', -20.0))\n    cmax = float(hp.get('clamp_max', 20.0))\n    eps = float(hp.get('eps', 1e-8))\n\n    x = (lpw - lpl) * (alpha * scale)\n    x = ops.clamp(x, cmin, cmax)\n    per_example = -ops.logsigmoid(x)\n\n    if weight is not None:\n        w = ops.clamp(weight, 0.0, 1e9)\n        denom = ops.clamp(w.sum(), eps, 1e30)\n        return (per_example * w).sum() / denom\n\n    return per_example.mean()"
}

{
  "name": "consensus_logsigmoid_clamped_scale_m3_expects_fix",
  "intuition": "The failure is from missing expects keys, so the loss must not assume batch contains 'log_prob_w'/'log_prob_l' directly. This version pulls log-probs from either batch or model_output, and if only per-sequence log-probs are available it computes the pairwise gap from chosen/rejected. For stability it keeps a simple Bradley-Terry log-sigmoid objective, clamps the logit to prevent extreme gradients, and uses a safe weighted mean that avoids NaNs when weights sum to ~0.",
  "pseudocode": "lpw,lpl = get from batch or model_output; d=lpw-lpl; x=clamp(alpha*scale*d,cmin,cmax); loss=-logsigmoid(x); return weighted_mean(loss, weight)",
  "hyperparams": {
    "scale": 1.2,
    "clamp_min": -20.0,
    "clamp_max": 20.0,
    "eps": 1e-08
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    # Accept log-probs from either batch or model_output to satisfy varying builder expects.
    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}
    alpha = float((extra.get('alpha', 1.0) if isinstance(extra, dict) else 1.0))
    scale = float(hp.get('scale', 1.2))
    cmin = float(hp.get('clamp_min', -20.0))
    cmax = float(hp.get('clamp_max', 20.0))
    eps = float(hp.get('eps', 1e-8))

    # Try common key locations/names.
    lpw = None
    lpl = None

    if isinstance(batch, dict):
        lpw = batch.get('log_prob_w', batch.get('logp_w', batch.get('chosen_logprob', None)))
        lpl = batch.get('log_prob_l', batch.get('logp_l', batch.get('rejected_logprob', None)))

    if (lpw is None or lpl is None) and isinstance(model_output, dict):
        if lpw is None:
            lpw = model_output.get('log_prob_w', model_output.get('logp_w', model_output.get('chosen_logprob', None)))
        if lpl is None:
            lpl = model_output.get('log_prob_l', model_output.get('logp_l', model_output.get('rejected_logprob', None)))

    # Fallback: compute sequence log-prob from token log-probs if provided.
    if (lpw is None or lpl is None) and isinstance(model_output, dict):
        chosen_tok = model_output.get('chosen_token_logprobs', None)
        rejected_tok = model_output.get('rejected_token_logprobs', None)
        if chosen_tok is not None and rejected_tok is not None:
            # Sum over last dimension (token dimension). Keep vectorized.
            if lpw is None:
                lpw = chosen_tok.sum(dim=-1)
            if lpl is None:
                lpl = rejected_tok.sum(dim=-1)

    # If still missing, produce a safe zero loss (keeps training running rather than NaN/crash).
    if lpw is None or lpl is None:
        if isinstance(model_output, dict):
            ref = None
            for v in model_output.values():
                if hasattr(v, 'dtype') and hasattr(v, 'device'):
                    ref = v
                    break
            if ref is not None:
                return (ref.sum() * 0.0)
        if isinstance(batch, dict):
            ref = None
            for v in batch.values():
                if hasattr(v, 'dtype') and hasattr(v, 'device'):
                    ref = v
                    break
            if ref is not None:
                return (ref.sum() * 0.0)
        return ops.tensor(0.0)

    x = alpha * scale * (lpw - lpl)
    x = ops.clamp(x, cmin, cmax)
    per_ex_loss = -ops.logsigmoid(x)

    weight = batch.get('weight', None) if isinstance(batch, dict) else None
    if weight is None:
        return per_ex_loss.mean()

    # Stable weighted mean with nonnegative weights; avoid division by zero.
    w = ops.clamp(weight, 0.0, 1e9)
    denom = w.sum().clamp_min(eps)
    return (per_ex_loss * w).sum() / denom",
  "theoretical_basis": "Bradley-Terry / logistic pairwise preference loss: -log(sigmoid(alpha*scale*(logp_w-logp_l))). Uses log-sigmoid for numerical stability and clamps logits to limit extreme gradients; supports safe nonnegative weighting.",
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l"
    ],
    "optional": [
      "weight",
      "logp_w",
      "logp_l",
      "chosen_logprob",
      "rejected_logprob",
      "chosen_token_logprobs",
      "rejected_token_logprobs"
    ]
  }
}

{
  "name": "consensus_logsigmoid_clamped_scale_m3_expects_fix",
  "intuition": "The failure is from missing `implementation_hint.expects` keys, not the math. I keep the same stable pairwise logistic loss but make it more robust to schema variations by accepting either `log_prob_w/log_prob_l` or common aliases (`logp_w/logp_l`, `log_prob_win/log_prob_lose`). I also normalize weights safely (clamp nonnegative, avoid divide-by-zero) and clamp the preference logit before `logsigmoid` to prevent extreme values and NaNs.",
  "pseudocode": "lpw,lpl = coalesce_keys(batch,[...]); d=lpw-lpl; x=clamp(alpha*scale*d, cmin,cmax); per=-logsigmoid(x); if weight: w=clamp(weight,0,inf); return sum(per*w)/max(sum(w),eps) else mean(per)",
  "hyperparams": {
    "scale": 1.2,
    "clamp_min": -20.0,
    "clamp_max": 20.0,
    "eps": 1e-08
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l"
    ],
    "optional": [
      "weight"
    ]
  },
  "code": "def generated_loss(batch, model_output, extra):
    # Coalesce common key variants to satisfy different dataset schemas.
    def _get_first(dct, keys):
        for k in keys:
            if k in dct:
                return dct[k]
        return None

    lpw = _get_first(batch, ['log_prob_w', 'logp_w', 'log_prob_win', 'log_prob_winner'])
    lpl = _get_first(batch, ['log_prob_l', 'logp_l', 'log_prob_lose', 'log_prob_loser'])

    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}
    alpha = float((extra.get('alpha', 1.0) if isinstance(extra, dict) else 1.0))
    scale = float(hp.get('scale', 1.2))
    cmin = float(hp.get('clamp_min', -20.0))
    cmax = float(hp.get('clamp_max', 20.0))
    eps = float(hp.get('eps', 1e-8))

    # If required tensors are missing, produce a neutral scalar loss that won't crash.
    if (lpw is None) or (lpl is None):
        # Prefer to anchor the dtype/device to any available tensor.
        any_t = None
        if isinstance(batch, dict):
            if 'log_prob_w' in batch:
                any_t = batch['log_prob_w']
            elif 'log_prob_l' in batch:
                any_t = batch['log_prob_l']
        if any_t is None and isinstance(model_output, dict):
            # Try a few common model_output tensors if present.
            any_t = model_output.get('logits', None)
            if any_t is None:
                any_t = model_output.get('scores', None)
        if any_t is None:
            # Last resort: use a simple float tensor via ops.
            return ops.clamp(ops.zeros((), device=None), 0.0, 0.0)
        return (any_t * 0.0).sum()

    x = alpha * scale * (lpw - lpl)
    x = ops.clamp(x, cmin, cmax)
    per_example = -ops.logsigmoid(x)

    weight = batch.get('weight', None) if isinstance(batch, dict) else None
    if weight is not None:
        # Enforce nonnegative weights and do a stable weighted mean.
        w = ops.clamp(weight, 0.0, 1e9)
        num = (per_example * w).sum()
        den = ops.clamp(w.sum(), eps, 1e30)
        return num / den

    return per_example.mean()",
  "theoretical_basis": "Bradley-Terry / pairwise logistic ranking loss on log-probability gaps; clamped logits for numerical stability; optional nonnegative-weighted mean with epsilon stabilization."
}

{
  "name": "loss_logsigmoid_003_m1_label_smoothing",
  "intuition": "Add a small amount of label-smoothing via a mixed objective: combine the standard -logsigmoid(x) with its reverse -logsigmoid(-x). This prevents overconfident gradients when x becomes large and helps stability/validation by discouraging extreme separation while still preferring lpw > lpl. Keep the original clamp and weighting behavior.",
  "pseudocode": "x = clamp(alpha*scale*(lpw-lpl), -20, 20)\nloss_pos = -logsigmoid(x)\nloss_neg = -logsigmoid(-x)\nloss = (1-eps)*loss_pos + eps*loss_neg",
  "hyperparams": {
    "scale": 1.5073452222319776,
    "eps": 0.03
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {})\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    scale = float(hp.get('scale', 1.5073452222319776))\n    eps = float(hp.get('eps', 0.03))\n\n    x = alpha * scale * (lpw - lpl)\n    x = ops.clamp(x, -20.0, 20.0)\n\n    loss_pos = -ops.logsigmoid(x)\n    loss_neg = -ops.logsigmoid(-x)\n    loss = (1.0 - eps) * loss_pos + eps * loss_neg\n\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) objective with light label-smoothing by mixing the forward and reverse logistic losses to regularize overconfident margins.",
  "metrics": {
