        "log_prob_l": "tensor[batch]",
        "weight": "optional tensor[batch] nonnegative"
      },
      "model_output": "unused",
      "extra": {
        "alpha": "optional float",
        "hyperparams": {
          "scale": "float",
          "eps": "float in [0, 0.2] recommended"
        }
      }
    },
    "returns": "scalar torch.Tensor"
